// Fingerprint Inquiry: builds a duplicate key from the sender's email and message, and the time window to check.
const s = $('Load Client Settings').first().json;
const inq = $json;
const norm = function (v) { return String(v == null ? '' : v).toLowerCase().replace(/\s+/g, ' ').trim(); };
const text = norm(inq.email) + '|' + norm(inq.message);
const fnv = function (str, seed) {
  let h = seed >>> 0;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
};
const raw = s.dedupe_minutes;
const minutes = raw === undefined || raw === null || String(raw).trim() === '' ? 10 : Math.max(0, Number(raw) || 0);
return {
  json: Object.assign({}, inq, {
    dedupe_key: 'fp_' + fnv(text, 0x811c9dc5) + fnv(text, 0x9747b28c) + '_' + text.length.toString(16),
    dedupe_cutoff: $now.minus({ minutes: minutes }).toUTC().toISO()
  })
};

