// Build Inquiry Record: reads Claude's JSON (or falls back safely), creates the record, and composes both emails.
// ---- Shared email helpers (inserted by the build into every Code node that sends branded email) ----
const esc = function (v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); };
const FONT = "Inter,-apple-system,'Segoe UI',Helvetica,Arial,sans-serif";
const MONO = "'IBM Plex Mono',Menlo,Consolas,monospace";
const P = function (t) { return '<p style="margin:0 0 14px">' + t + '</p>'; };
const setting = function (s, key, fallback) { const v = s ? s[key] : undefined; return v === undefined || v === null || String(v).trim() === '' ? fallback : v; };
const button = function (url, label) { return '<table role="presentation" cellpadding="0" cellspacing="0" style="margin:4px 0 10px"><tr><td style="background:#1f2124;border-radius:999px"><a href="' + esc(url) + '" style="display:inline-block;padding:12px 22px;font:500 14px/1 ' + FONT + ';color:#ffffff;text-decoration:none;border-radius:999px">' + esc(label) + '</a></td></tr></table>'; };
const hostOf = function (url) { try { return new URL(String(url)).hostname.replace(/^www\./, ''); } catch (e) { return ''; } };
const brandHeader = function (s) {
  const name = esc(setting(s, 'firm_name', 'Our team'));
  const logo = setting(s, 'logo_url', '');
  if (logo) {
    const w = Number(setting(s, 'logo_width', 152)) || 152;
    const h = Number(setting(s, 'logo_height', 24)) || 24;
    return '<img src="' + esc(logo) + '" width="' + w + '" height="' + h + '" alt="' + name + '" style="display:block;border:0;outline:none;color:#f3f3f1;font:600 14px/24px Arial,sans-serif;letter-spacing:2px">';
  }
  return '<div style="color:#f3f3f1;font:600 15px/24px ' + FONT + ';letter-spacing:2px;text-transform:uppercase">' + name + '</div>';
};
const shell = function (s, inner, footExtra) {
  const firm = esc(setting(s, 'firm_name', ''));
  const addr = esc(setting(s, 'brand_address', ''));
  const site = setting(s, 'website_url', '');
  const mail = setting(s, 'public_email', '');
  const contact = [site ? '<a href="' + esc(site) + '" style="color:#565b62">' + esc(hostOf(site) || site) + '</a>' : '', mail ? esc(mail) : ''].filter(Boolean).join(' &middot; ');
  return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"></head><body style="margin:0;padding:0;background:#f3f3f1">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f3f1"><tr><td align="center" style="padding:24px 12px">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border:1px solid #dcdddb;border-radius:12px;border-collapse:separate;overflow:hidden">' +
    '<tr><td style="background:#121315;padding:22px 28px;border-radius:12px 12px 0 0">' + brandHeader(s) + '</td></tr>' +
    '<tr><td style="padding:28px;font:15px/1.6 ' + FONT + ';color:#1f2124">' + inner + '</td></tr>' +
    '<tr><td style="background:#f3f3f1;border-top:1px solid #dcdddb;padding:20px 28px;font:12px/1.7 ' + FONT + ';color:#565b62;border-radius:0 0 12px 12px">' +
    (firm || addr ? '<div style="font-family:' + MONO + ';font-size:11px;letter-spacing:1.3px;text-transform:uppercase;color:#6f747b">' + [firm, addr].filter(Boolean).join(' &middot; ') + '</div>' : '') +
    (contact ? '<div>' + contact + '</div>' : '') +
    (footExtra ? '<div>' + footExtra + '</div>' : '') +
    '</td></tr></table></td></tr></table></body></html>';
};
const windowText = function (hours) {
  const h = Number(hours);
  if (!(h > 0)) return 'soon';
  if (h <= 1) return 'within the hour';
  if (h < 24) return 'within ' + Math.round(h) + ' hours';
  if (h === 24) return 'within one business day';
  return 'within ' + Math.round(h / 24) + ' business days';
};
// ---- End shared helpers ----
const inq = $('Fingerprint Inquiry').item.json;
const s = $('Load Client Settings').first().json;
const hook = $('Inquiry Received').first().json;
const j = $json || {};
let raw = '';
if (typeof j.text === 'string') raw = j.text;
else if (Array.isArray(j.content)) raw = j.content.filter(function (c) { return c && c.type === 'text'; }).map(function (c) { return c.text; }).join('');
else if (typeof j.output === 'string') raw = j.output;
else if (j.message && typeof j.message.content === 'string') raw = j.message.content;
let ai = null;
try { const a = raw.indexOf('{'); const b = raw.lastIndexOf('}'); if (a >= 0 && b > a) ai = JSON.parse(raw.slice(a, b + 1)); } catch (e) { ai = null; }
const clip = function (v, n) { return String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, n); };
const words = String(inq.message || '').split(/\s+/);
const urgency = ai && ['urgent', 'normal', 'low'].indexOf(ai.urgency) >= 0 ? ai.urgency : 'normal';
const isSpam = !!(ai && ai.is_spam === true && Number(ai.confidence) >= 0.7);
const slaHours = urgency === 'urgent' ? Number(setting(s, 'urgent_sla_hours', 4)) : Number(setting(s, 'reply_sla_hours', 24));
const ttlDays = Number(setting(s, 'token_ttl_days', 30));
const rand = function (n) {
  if (typeof crypto !== 'undefined' && crypto.getRandomValues) { const a = new Uint8Array(n); crypto.getRandomValues(a); return Array.from(a).map(function (x) { return x.toString(16).padStart(2, '0'); }).join(''); }
  let o = ''; for (let i = 0; i < n * 2; i++) o += Math.floor(Math.random() * 16).toString(16); return o;
};
const ref = 'INQ-' + $now.toFormat('yyMMdd') + '-' + rand(3).toUpperCase();
const token = rand(24);
const firm = setting(s, 'firm_name', 'Our team');
const base = String(setting(s, 'n8n_base_url', '')).replace(/\/+$/, '') || String(hook.webhookUrl || '').replace(/\/webhook(-test)?\/flow-intake.*$/, '');
const link = function (st) { return base + '/webhook/flow-status?ref=' + encodeURIComponent(ref) + '&t=' + token + '&s=' + st; };
const first = clip(inq.name, 60).split(' ')[0] || 'there';
const now = $now.toUTC();
const rec = {
  inquiry_ref: ref, received_at: now.toISO(), name: inq.name, email: inq.email, company: inq.company, phone: inq.phone,
  message: inq.message, source: inq.source,
  topic: clip(ai && ai.topic ? ai.topic : 'General inquiry', 80),
  urgency: urgency,
  budget: clip(ai && ai.budget ? ai.budget : 'Not stated', 60),
  summary: clip(ai && ai.summary ? ai.summary : words.slice(0, 30).join(' ') + (words.length > 30 ? '...' : ''), 300),
  suggested_reply: String(ai && ai.suggested_reply ? ai.suggested_reply : '').trim().slice(0, 1200),
  is_spam: isSpam, status: isSpam ? 'spam' : 'new',
  reply_due_at: now.plus({ hours: slaHours }).toISO(), reminded: false, action_token: token,
  token_expires_at: ttlDays > 0 ? now.plus({ days: ttlDays }).toISO() : null,
  status_changed_at: now.toISO(), dedupe_key: inq.dedupe_key
};
const aiStatus = ai ? 'classified' : 'ai_unavailable';
const site = setting(s, 'website_url', '');
const ackSubject = 'Thanks, ' + first + '. We received your message';
const bookingLink = setting(s, 'booking_link', '');
const ackHtml = shell(s,
  P('Hi ' + esc(first) + ',') +
  P('Thank you for contacting ' + esc(firm) + '. We received your message about ' + esc(rec.topic.toLowerCase()) + ', and a member of our team will reply personally ' + windowText(slaHours) + '.') +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:2px 0 18px;background:#f3f3f1;border:1px solid #dcdddb;border-radius:10px;border-collapse:separate"><tr><td style="padding:14px 16px"><div style="font-family:' + MONO + ';font-size:11px;letter-spacing:1.1px;text-transform:uppercase;color:#6f747b">Your request</div><div>' + (inq.company ? esc(inq.company) + ' &middot; ' : '') + '<span style="white-space:nowrap">Reference ' + ref + '</span></div></td></tr></table>' +
  (bookingLink ? P('If it helps, you can choose a time for a first call now.') + button(bookingLink, setting(s, 'booking_cta_label', 'Book a call')) + (setting(s, 'booking_note', '') ? '<p style="margin:0;font-size:14px;color:#565b62">' + esc(s.booking_note) + '</p>' : '') : ''),
  'You&rsquo;re receiving this because you contacted ' + esc(firm) + (site ? ' through ' + esc(hostOf(site) || site) : '') + '. Just reply to reach us.'
);
const alertSubject = (urgency === 'urgent' ? '[Urgent] ' : '') + 'New inquiry: ' + clip(inq.name, 60) + (inq.company ? ', ' + clip(inq.company, 60) : '') + ' (' + ref + ')';
const btn = function (st, label) { return base ? '<a href="' + esc(link(st)) + '" style="display:inline-block;padding:8px 14px;margin:0 6px 6px 0;border-radius:999px;background:#1f2124;color:#fff;text-decoration:none">' + label + '</a>' : ''; };
const alertHtml = '<p><b>' + esc(rec.summary) + '</b></p>' +
  '<table cellpadding="4"><tr><td>Topic</td><td>' + esc(rec.topic) + '</td></tr><tr><td>Urgency</td><td>' + esc(urgency) + '</td></tr><tr><td>Budget</td><td>' + esc(rec.budget) + '</td></tr><tr><td>From</td><td>' + esc(inq.name) + ' &lt;' + esc(inq.email) + '&gt;' + (inq.phone ? ', ' + esc(inq.phone) : '') + '</td></tr><tr><td>Reply due</td><td>' + esc($now.plus({ hours: slaHours }).toFormat('ccc d LLL, h:mm a')) + '</td></tr></table>' +
  '<p><b>Their message</b></p><blockquote>' + esc(inq.message).replace(/\n/g, '<br>') + '</blockquote>' +
  (rec.suggested_reply ? '<p><b>Suggested reply (review before sending)</b></p><blockquote>' + esc(rec.suggested_reply).replace(/\n/g, '<br>') + '</blockquote>' : '<p>AI sorting was unavailable for this inquiry.</p>') +
  '<p>' + btn('replied', 'I replied to them') + btn('won', 'Became a client') + btn('lost', 'Close: no deal') + '</p>' +
  '<p style="color:#666;font-size:13px;line-height:1.6"><b>I replied to them</b>: stops reminders. Nothing is sent to them.<br><b>Became a client</b>: sends them the welcome and onboarding email.<br><b>Close: no deal</b>: for no reply, went elsewhere, or a test. Nothing is sent to them.</p>' +
  '<p style="color:#666">Reference ' + ref + (ttlDays > 0 ? '. These buttons work for ' + ttlDays + ' days.' : '') + '</p>';
return { json: Object.assign({}, rec, { ai_status: aiStatus, ai_reasoning: ai && ai.reasoning ? clip(ai.reasoning, 200) : '', owner_email: s.owner_email, firm_name: firm, ack_subject: ackSubject, ack_html: ackHtml, alert_subject: alertSubject, alert_html: alertHtml }) };
